L7_1 = {}
L7_1.m_CutScenKey_Talk = "CHARADE2_ACT4_INTERLUDE1@7#Talk"
L7_1.m_CutScenProcessKey = 7
L7_1.m_CutScenID = 5700401
L7_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_Talk_KOREA = "버넷 씨! 좀 더 고상한 포즈로 부탁드릴게요!"
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "バーネットさん！　もう少し高尚なポーズでお願いします！"
L7_1.m_Talk_ENG = "Mr. Burnett! Could you do a more elegant pose, please?"
L7_1.m_Talk_TWN = "伯內特！請擺一個再優雅一點的姿勢！"
L7_1.m_Talk_THA = "คุณเบอร์เน็ตต์! คุณช่วยทำท่าที่สง่างามกว่านี้หน่อยได้ไหม?"
L7_1.m_Talk_VTN = "Cậu Burnett! Cậu có thể tạo dáng thanh lịch hơn được không?"
L7_1.m_Talk_SCN = "伯内特先生！姿势请再高雅些！"
L7_1.m_Talk_DEU = "Herr Burnett! Könnten Sie bitte eine elegantere Pose machen?"
L7_1.m_Talk_FRA = "Monsieur Burnett ! Pourriez-vous prendre une pose plus élégante, s'il vous plaît ?"
L8_1 = {}
L8_1.m_CutScenKey_Talk = "CHARADE2_ACT4_INTERLUDE1@8#Talk"
L8_1.m_CutScenProcessKey = 8
L8_1.m_CutScenID = 5700401
L8_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Talk_KOREA = "뤼미에르 부티크의 브랜드 이미지에 걸맞은 고풍스러운 이미지를 보여주세요!"
L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "ルミエールブティックのブランドイメージにふさわしい、古風な感じでお願いします！"
L8_1.m_Talk_ENG = "Show us a sophisticated image that can represent the Lumiere Boutique brand!"
L8_1.m_Talk_TWN = "請表現出符合精品店的奢華形象！"
L8_1.m_Talk_THA = "แสดงให้เราเห็นภาพลักษณ์ที่ซับซ้อนที่สามารถเป็นตัวแทนของแบรนด์ ลูเมียร์ บูทีค!"
L8_1.m_Talk_VTN = "Hãy cho chúng tôi xem một hình ảnh tinh tế có thể đại diện cho thương hiệu Lumiere Boutique!"
L8_1.m_Talk_SCN = "要符合卢米埃精品店品牌形象的古典韵味！"
L8_1.m_Talk_DEU = "Präsentieren Sie ein exquisites Image, das zum Markenimage von Lumieres Boutique passt!"
L8_1.m_Talk_FRA = "Montrez-nous une image sophistiquée digne de la marque Lumière Boutique !"
