L13_1.m_Pos = "C"
L13_1.m_Talk_KOREA = "이래서 사진 찍는 건 딱 질색인데 말이야."
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "これだから写真撮影は大嫌いなんだ。"
L13_1.m_Talk_ENG = "This is why I said I didn't want to do a photoshoot."
L13_1.m_Talk_TWN = "就是因為這樣我才很討厭拍照。"
L13_1.m_Talk_THA = "เลยบอกว่าไม่อยากถ่ายรูป"
L13_1.m_Talk_VTN = "Đây là lý do tại sao tôi nói không muốn chụp ảnh."
L13_1.m_Talk_SCN = "就因为这样我才很讨厌拍照。"
L13_1.m_Talk_DEU = "Genau deshalb habe ich gesagt, dass ich kein Fotoshooting machen will."
L13_1.m_Talk_FRA = "C'est pour ça que j'ai dit que je voulais pas faire de séance photo."
