L20_1 = {}
L20_1.m_CutScenKey_Talk = "CHARADE2_ACT4_INTERLUDE1@20#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 5700401
L20_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Talk_KOREA = "어떠십니까, 초원 씨? 텍티칼 사의 신제품이랍니다."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "いかがでしょうか、スズキ・ナオさん？　テクティカル社の新製品です。"
L20_1.m_Talk_ENG = "What do you think of it, Miss Chowon? It's Tactical's newest product."
L20_1.m_Talk_TWN = "初源，這是裝備公司的新產品，你覺得怎麼樣？"
L20_1.m_Talk_THA = "คุณคิดอย่างไรกับเรื่องนี้ คุณโชวอน? เป็นผลิตภัณฑ์ใหม่ล่าสุดของเชิงยุทธวิธี"
L20_1.m_Talk_VTN = "Cô nghĩ sao, cô Chowon? Đây là sản phẩm chiến thuật mới nhất."
L20_1.m_Talk_SCN = "怎么样，桃沢梨绘小姐？这是TACTICAL公司的新产品。"
L20_1.m_Talk_DEU = "Was halten Sie davon, Chowon? Es ist das neueste Produkt von Tactical."
L20_1.m_Talk_FRA = "Qu'en pensez-vous, Mlle Chowon ? Il s'agit du nouveau produit de Tactical."
L21_1 = {}
L21_1.m_CutScenKey_Talk = "CHARADE2_ACT4_INTERLUDE1@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 5700401
L21_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Talk_KOREA = "최첨단 전술 장비 제조사라는 이미지에 걸맞게 뛰어난 스펙을 자랑하죠!"
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "最先端戦術装備製作会社というイメージにふさわしい優れた性能ですよ！"
L21_1.m_Talk_ENG = "Being the state-of-the-art gear manufacturer, our products also boast outstanding specifications!"
L21_1.m_Talk_TWN = "這間公司擁有最先進的製造技術，擅長製造最尖端的戰術裝備！"
L21_1.m_Talk_THA = "ในฐานะผู้ผลิตเกียร์ที่ล้ำสมัย ผลิตภัณฑ์ของเรายังมีคุณสมบัติโดดเด่นอีกด้วย!"
L21_1.m_Talk_VTN = "Là nhà sản xuất thiết bị hiện đại, các sản phẩm của chúng tôi cũng có thông số kỹ thuật vượt trội!"
L21_1.m_Talk_SCN = "作为最尖端的战术装备制造公司，我们的产品配置也一直是最新最好的！"
L21_1.m_Talk_DEU = "Passend zu seinem Image als Hersteller modernster taktischer Ausrüstung verfügen die Produkte auch über hervorragende Spezifikationen!"
L21_1.m_Talk_FRA = "En tant que fabricant d'équipements tactiques de pointe, nos produits offrent également des caractéristiques exceptionnelles !"
L22_1 = {}
L22_1.m_CutScenKey_Talk = "CHARADE2_ACT4_INTERLUDE1@22#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 5700401
L22_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_Talk_KOREA = "전 세계 태스크포스 업계가 이 광고를 주목하고 있을 겁니다. 한 말씀 남겨 주시죠!"
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "世界中のタスクフォース業界がこの宣伝を見ていると思います。一言お願いします！"
L22_1.m_Talk_ENG = "TASKFORCEs around the globe will be watching this ad. A word, if you will?"
L22_1.m_Talk_TWN = "全世界的特遣勢力都在關注這個廣告，請你說句話吧！"
L22_1.m_Talk_THA = "ทาสก์ฟอร์สทั่วโลกจะดูโฆษณานี้ คำว่าถ้าคุณจะ?"
L22_1.m_Talk_VTN = "TASKFORCE trên toàn cầu sẽ xem quảng cáo này. Một lời thôi, nếu cô sẵn sàng?"
L22_1.m_Talk_SCN = "全世界的特遣势力都会看到这个广告的，请说一句感想吧！"
L22_1.m_Talk_DEU = "TASKFORCEs auf der ganzen Welt werden sich diese Werbung ansehen. Könnten Sie uns kurz Ihre Meinung zu dieser Ausrüstung mitteilen?"
L22_1.m_Talk_FRA = "Les TASKFORCEs du monde entier regarderont cette annonce. Voulez-vous dire un mot ?"
