L26_1.m_Face = "UNIT_LAUGH"
L26_1.m_CharStrID = "CHOWON_PERSONA_NULL_NULL"
L26_1.m_Pos = "C"
L26_1.m_Talk_KOREA = "훌륭한 장비네요. 보험사에서 특히 좋아하겠어요."
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "素晴らしい装備ですね。特に保険会社に喜ばれると思います。"
L26_1.m_Talk_ENG = "This gear is excellent. I'm sure the insurance companies would especially love it."
L26_1.m_Talk_TWN = "是很出色的裝備，保險公司應該會很喜歡。"
L26_1.m_Talk_THA = "เกียร์นี้เยี่ยมมาก ฉันแน่ใจว่าบริษัทประกันภัยจะชอบมันเป็นพิเศษ"
L26_1.m_Talk_VTN = "Thiết bị này rất xuất sắc. Tôi chắc chắn rằng các công ty bảo hiểm sẽ đặc biệt yêu thích nó."
L26_1.m_Talk_SCN = "是很优秀的装备，我相信保险公司应该会特别喜欢。"
L26_1.m_Talk_DEU = "Diese Ausrüstung ist ausgezeichnet. Ich bin mir sicher, dass sie den Versicherungsgesellschaften besonders gefallen dürfte."
L26_1.m_Talk_FRA = "Cet équipement est remarquable. Je suis sûre que les compagnies d'assurance l'adoreront tout particulièrement."
