L27_1.m_Face = "UNIT_HATE"
L27_1.m_CharStrID = "CHOWON_PERSONA_NULL_NULL"
L27_1.m_Pos = "C"
L27_1.m_Talk_KOREA = "직설적으로 말씀드리면, 겉멋 든 장비보단 구식이라도 신뢰도가 높은 쪽이 낫다는 뜻이에요."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "ストレートに言いますと、見た目だけの装備より、旧式であっても信頼性の高い装備の方がいいということです。"
L27_1.m_Talk_ENG = "In other words, it's better to have reliable gear, even if it's older than those flashy ones."
L27_1.m_Talk_TWN = "說直接一點就是，雖然是舊款，但還是比那些中看不中用的裝備好，至少是可信賴的公司生產的。"
L27_1.m_Talk_THA = "กล่าวอีกนัยหนึ่ง การมีอุปกรณ์ที่เชื่อถือได้จะดีกว่า แม้ว่าจะเก่ากว่าอุปกรณ์ที่ฉูดฉาดเหล่านั้นก็ตาม"
L27_1.m_Talk_VTN = "Nói cách khác, tốt hơn là nên có những thiết bị đáng tin cậy, ngay cả khi nó cũ hơn mấy đồ hào nhoáng đó."
L27_1.m_Talk_SCN = "我是说，它最好有那么可靠，就算款式旧一点，也比徒有其表来得好。"
L27_1.m_Talk_DEU = "Mit anderen Worten, es ist besser, eine äußerst zuverlässige Ausrüstung zu haben, auch wenn sie veraltet ist, als eine Ausrüstung, die lediglich hübsch anzusehen ist."
L27_1.m_Talk_FRA = "En d'autres termes, il est préférable d'avoir un équipement fiable, même s'il est obsolète par rapport aux équipements plus sophistiqués."
