L30_1 = {}
L30_1.m_CutScenKey_Talk = "CHARADE2_ACT4_INTERLUDE1@30#Talk"
L30_1.m_CutScenProcessKey = 30
L30_1.m_CutScenID = 5700401
L30_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_Talk_KOREA = "슈가 브래드에서 만든 마카롱이 세상에서 가장 맛있는 것처럼~!"
L30_1.m_fTalkTime = 0.03
L30_1.m_Talk_JPN = "シュガーブランドが作ったマカロンが世界一美味しいといった感じで～！"
L30_1.m_Talk_ENG = "Imagine that macarons made by Sugar Bread are the best in the world!"
L30_1.m_Talk_TWN = "好像糖果公司生產的馬卡龍是世界上最好吃的馬卡龍，差不多這種感覺～！"
L30_1.m_Talk_THA = "ลองนึกภาพมาการองที่ทำโดยขนมปังน้ำตาลนั้นดีที่สุดในโลก!"
L30_1.m_Talk_VTN = "Hãy tưởng tượng rằng bánh macaron do Sugar Bread làm là ngon nhất thế giới!"
L30_1.m_Talk_SCN = "请想象一下，糖果品牌生产的马卡龙是世界上最好吃的马卡龙~！"
L30_1.m_Talk_DEU = "Stell dir einfach vor, die Macarons von Zuckerbrot sind die leckersten der Welt!"
L30_1.m_Talk_FRA = "C'est comme les macarons de Sugar Bread ! Les meilleurs du monde !"
L31_1 = {}
L31_1.m_CutScenKey_Talk = "CHARADE2_ACT4_INTERLUDE1@31#Talk"
L31_1.m_CutScenProcessKey = 31
L31_1.m_CutScenID = 5700401
L31_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Talk_KOREA = "자, 그럼 찍겠습니다."
L31_1.m_fTalkTime = 0.03
L31_1.m_Talk_JPN = "じゃあ、撮りますよ。"
L31_1.m_Talk_ENG = "Okay, action!"
L31_1.m_Talk_TWN = "好，正式開拍囉。"
L31_1.m_Talk_THA = "เอาล่ะ ลงมือทำ!"
L31_1.m_Talk_VTN = "Được rồi, hành động!"
L31_1.m_Talk_SCN = "那么，预备——开拍！"
L31_1.m_Talk_DEU = "Okay! Action!"
L31_1.m_Talk_FRA = "Bon, action !"
