L46_1 = {}
L46_1.m_CutScenKey_Talk = "CHARADE2_ACT4_INTERLUDE1@46#Talk"
L46_1.m_CutScenProcessKey = 46
L46_1.m_CutScenID = 5700401
L46_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_Face = "UNIT_DESPAIR"
L46_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L46_1.m_Pos = "L"
L46_1.m_Talk_KOREA = "한쪽에서는 못 죽여서 안달인데 다른 한쪽에서는 스폰서 광고 모델을 맡겨?"
L46_1.m_fTalkTime = 0.03
L46_1.m_Talk_JPN = "私たちを殺したがってる連中がいる一方で、広告モデルを頼んでくるスポンサーがいるなんてな。"
L46_1.m_Talk_ENG = "One side is out to kill us, but the other wants us to be advertising models for our sponsors?"
L46_1.m_Talk_TWN = "一邊是恨不得想趕快除掉我們，另一邊卻找我們當贊助商的廣告模特兒？"
L46_1.m_Talk_THA = "ฝ่ายหนึ่งตั้งใจจะฆ่าเรา แต่อีกฝ่ายอยากให้เราเป็นนางแบบโฆษณาให้สปอนเซอร์ของเรา?"
L46_1.m_Talk_VTN = "Một bên muốn giết chúng ta, nhưng bên kia lại muốn chúng ta làm người mẫu quảng cáo cho các nhà tài trợ?"
L46_1.m_Talk_SCN = "一方急着想要杀掉我们，而另一方请我们当广告模特还来不及？"
L46_1.m_Talk_DEU = "Die eine Seite will uns töten, aber die andere will, dass wir Werbemodelle für unsere Sponsoren sind?"
L46_1.m_Talk_FRA = "D'un côté y'a ceux qui veulent nous tuer, et de l'autre ceux qui veulent faire de nous des modèles publicitaires pour nos sponsors..."
L47_1 = {}
L47_1.m_CutScenKey_Talk = "CHARADE2_ACT4_INTERLUDE1@47#Talk"
L47_1.m_CutScenProcessKey = 47
L47_1.m_CutScenID = 5700401
L47_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_Face = "UNIT_PRIDE"
L47_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L47_1.m_Pos = "L"
L47_1.m_Crash = 10
L47_1.m_Talk_KOREA = "우리가 우승까지 하면 꼴이 꽤 볼 만하겠구만."
L47_1.m_fTalkTime = 0.03
L47_1.m_Talk_JPN = "優勝したらどんな顔をするか見物だね。"
L47_1.m_Talk_ENG = "It'll be really something if we actually win this thing."
L47_1.m_Talk_TWN = "要是我們最後真的奪冠，那就精彩囉。"
L47_1.m_Talk_THA = "มันจะเป็นอะไรจริงๆ ถ้าเราชนะสิ่งนี้จริงๆ"
L47_1.m_Talk_VTN = "Sẽ thực sự là một cái gì đó nếu chúng ta thực sự giành được chiến thắng này."
L47_1.m_Talk_SCN = "如果最后我们夺冠了，那就有戏可看了。"
L47_1.m_Talk_DEU = "Es wäre ein wahres Spektakel, wenn wir dieses Ding tatsächlich gewinnen."
L47_1.m_Talk_FRA = "Si on réussit à remporter la victoire, je crois qu'on va être servis."
