L53_1 = 0.15
L51_1[1] = L52_1
L51_1[2] = L53_1
L50_1.m_Bounce = L51_1
L51_1 = "하루에 광고 촬영만 5개! 이래서는 훈련할 시간도 없겠어요!"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "今日だけで広告撮影が五つも！　これじゃ訓練もできません！"
L50_1.m_Talk_JPN = L51_1
L51_1 = "We've done 5 commercials in one day! I don't know if we even have time to train!"
L50_1.m_Talk_ENG = L51_1
L51_1 = "我一天之內就拍了5個廣告！這樣下去都沒時間訓練了啦！"
L50_1.m_Talk_TWN = L51_1
L51_1 = "เราทำโฆษณา 5 ชิ้นในวันเดียว! ไม่รู้ว่าเราจะมีเวลาซ้อมหรือเปล่า!"
L50_1.m_Talk_THA = L51_1
L51_1 = "Chúng ta đã thực hiện 5 quảng cáo trong một ngày! Liệu chúng ta có thời gian để tập luyện không!"
L50_1.m_Talk_VTN = L51_1
L51_1 = "光是一天就拍了5个广告！这样下去都没时间训练了！"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Wir haben 5 Werbespots an einem Tag gedreht! Ich weiß nicht, ob wir überhaupt noch Zeit zum Trainieren haben!"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Nous avons fait 5 publicités en une journée ! Je crois que nous n'aurons même pas le temps de nous entraîner !"
L50_1.m_Talk_FRA = L51_1
