L6_1 = "헙!? 지금 훈련량이 부족하다는 뜻은 아니에요, 펠리세트!"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "はっ！？　今のは訓練量が足りないという意味ではありませんよ、フェリセット！"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Oops?! I didn't mean that the training we do now is not enough, Félicette!"
L5_1.m_Talk_ENG = L6_1
L6_1 = "呃？！費莉塞特，我不是指訓練量不夠的意思喔！"
L5_1.m_Talk_TWN = L6_1
L6_1 = "อ๊ะ?! ฉันไม่ได้หมายความว่าการฝึกฝนที่เราทำตอนนี้ยังไม่เพียงพอเฟลิเซ็ต!"
L5_1.m_Talk_THA = L6_1
L6_1 = "Ối?! Ý tôi không phải là việc tập luyện hiện tại của chúng ta là chưa đủ, Félicette!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "啊？！我不是说训练量不够，菲利塞特！"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Ähm?! Ich meinte damit nicht, dass unser jetziges Training nicht ausreicht, Felicette!"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Oups ! Enfin, ce n'est pas comme si l'entraînement que nous faisons actuellement n'était pas déjà suffisant, Felicette !"
L5_1.m_Talk_FRA = L6_1
