L8_1 = "전 아무 말도 안 했는데요."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "私は何も言ってません。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "I didn't say anything."
L7_1.m_Talk_ENG = L8_1
L8_1 = "我又沒說什麼。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ฉันไม่ได้พูดอะไร"
L7_1.m_Talk_THA = L8_1
L8_1 = "Tôi chưa nói gì cả."
L7_1.m_Talk_VTN = L8_1
L8_1 = "我什么话都没说啊。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Ich habe doch gar nichts gesagt."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Je n'ai rien dit."
