L8_1.m_Pos = "C"
L9_1 = "광고 촬영도 선수 활동의 일환이에요."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "広告撮影も選手活動の一環です。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Shooting commercials is a part of being a Gauntlet player."
L8_1.m_Talk_ENG = L9_1
L9_1 = "拍攝廣告也是選手工作的一環。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "การยิงโฆษณาเป็นส่วนหนึ่งของการเป็นผู้เล่นกอนต์เล็ต"
L8_1.m_Talk_THA = L9_1
L9_1 = "Quay quảng cáo là một phần của việc trở thành người chơi Gauntlet."
L8_1.m_Talk_VTN = L9_1
L9_1 = "拍摄广告也是选手活动的一环。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Auch das Drehen von Werbespots gehört zu den Aktivitäten eines Fehde-Spielers."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Tourner des publicités fait partie des activités d'un joueur de la Compétition."
L8_1.m_Talk_FRA = L9_1
