L9_1.m_Face = "UNIT_PRIDE"
L9_1.m_CharStrID = "FELICETTE_CANARY_NULL_NULL"
L9_1.m_Pos = "C"
L10_1 = "이건 그만큼 우리가 유명해졌다는 뜻이니까."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "それだけ私たちが有名になったということですから。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "It also means that we're famous."
L9_1.m_Talk_ENG = L10_1
L10_1 = "這就表示我們紅了。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ก็หมายความว่าเรามีชื่อเสียงด้วย"
L9_1.m_Talk_THA = L10_1
L10_1 = "Nó cũng có nghĩa là chúng ta nổi tiếng."
L9_1.m_Talk_VTN = L10_1
L10_1 = "这说明我们出名了。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Es bedeutet auch, dass wir berühmt sind."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Cela signifie également que nous sommes célèbres."
L9_1.m_Talk_FRA = L10_1
