L13_1 = "UNIT_IDLE"
L12_1.m_Face = L13_1
L12_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L12_1.m_Pos = "L"
L13_1 = "광고 좀 받았다고 우쭐대긴. 입에 묻은 마카롱 가루나 닦으셔."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "広告にちょっと出たからって調子に乗っちゃって。とりあえず口元についたマカロンから拭きなよ。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Don't be so cocky just because we did some commercials. How about wiping the macaron dust off your lips first?"
L12_1.m_Talk_ENG = L13_1
L13_1 = "拍了個廣告就得意忘形，先你把嘴角的馬卡龍渣渣擦乾淨吧。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "อย่าอวดดีเพียงเพราะเราทำโฆษณามาบ้าง ลองเช็ดฝุ่นมาการองออกจากริมฝีปากก่อนไหม?"
L12_1.m_Talk_THA = L13_1
L13_1 = "Đừng quá tự mãn chỉ vì đã đóng vài quảng cáo. Trước tiên hãy lau sạch bụi macaron khỏi môi cô nhé?"
L12_1.m_Talk_VTN = L13_1
L13_1 = "拍了个广告就得意忘形了，你把嘴角的马卡龙碎渣擦擦吧。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Sei nicht so übermütig, nur weil wir ein paar Werbespots gedreht haben. Wie wäre es, wenn du erst mal das Macaron-Pulver von deinen Lippen wischst?"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Redescends sur terre, on n'a fait que quelques publicités. Commence déjà par essayer les miettes de macarons que tu as autour des lèvres."
L12_1.m_Talk_FRA = L13_1
