L16_1 = "UNIT_IDLE"
L15_1.m_Face = L16_1
L15_1.m_CharStrID = "FELICETTE_CANARY_NULL_NULL"
L15_1.m_Pos = "C"
L16_1 = "동시에 결승 진출이 현실로 이루어졌다는 뜻이고요."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "決勝進出の夢が叶ったということでもあります。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "It means that we achieved our goal of making it to the finals."
L15_1.m_Talk_ENG = L16_1
L16_1 = "這也就表示，我要打進決賽的夢想成真了。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "หมายความว่าเราบรรลุเป้าหมายในการผ่านเข้ารอบชิงชนะเลิศ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Điều đó có nghĩa là chúng ta đã đạt được mục tiêu lọt vào trận chung kết."
L15_1.m_Talk_VTN = L16_1
L16_1 = "说明同时实现了进入决赛的梦想。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Gleichzeitig bedeutet es auch, dass der Einzug ins Finale endlich wahr geworden ist."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Cela signifie que nous avons atteint notre objectif de nous rendre en finale."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "CHARADE2_ACT4_INTERLUDE1@66#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 66
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 5700401
