L16_1.m_Face = "UNIT_LAUGH"
L16_1.m_CharStrID = "FELICETTE_CANARY_NULL_NULL"
L16_1.m_Pos = "C"
L16_1.m_Crash = 10
L17_1 = "다들 고마워요. 여기까지 저를 도와주셔서."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "みんなありがとうございます。ここまで私の力になってくれて。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Thanks, everyone. For helping me come this far."
L16_1.m_Talk_ENG = L17_1
L17_1 = "謝謝大家一直以來的幫助。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ขอบคุณทุกคน ที่ช่วยให้ฉันมาได้ไกลขนาดนี้"
L16_1.m_Talk_THA = L17_1
L17_1 = "Cảm ơn mọi người. Vì đã giúp tôi đi xa đến thế này."
L16_1.m_Talk_VTN = L17_1
L17_1 = "谢谢大家一直帮我到现在。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Vielen Dank an alle. Dafür, dass ihr mir geholfen habt, es so weit zu schaffen."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Merci tout le monde. De m'aider à aller aussi loin."
L16_1.m_Talk_FRA = L17_1
