L20_1 = "UNIT_IDLE"
L19_1.m_Face = L20_1
L19_1.m_CharStrID = "INTERN_FENRIR_NULL_NULL"
L19_1.m_Pos = "R"
L20_1 = "무슨 소리에요. 이제 건틀렛 리그 우승은 저희 모두의 꿈인 걸요."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "何言ってるんですか。もうガントレットリーグ優勝は私たち全員の夢ですよ。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "What are you talking about? Winning the Gauntlet is all of our dreams now."
L19_1.m_Talk_ENG = L20_1
L20_1 = "胡說什麼，現在拿到聖鎧聯賽冠軍可是我們所有人的夢想。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "คุณกำลังพูดถึงอะไร? การชนะก๊อตเล็ทคือความฝันของเราตอนนี้"
L19_1.m_Talk_THA = L20_1
L20_1 = "Nhóc đang nói gì vậy? Chiến thắng Gauntlet là giấc mơ của tất cả chúng ta bây giờ."
L19_1.m_Talk_VTN = L20_1
L20_1 = "说什么呢，现在拿到圣铠联赛的冠军是我们所有人的梦想了。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Wovon redest du? Die Fehde-Liga zu gewinnen ist jetzt unser aller Traum geworden."
L19_1.m_Talk_DEU = L20_1
L20_1 = "De quoi parles-tu ? Gagner la Compétition est notre rêve à tous à présent."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
