L20_1.m_Bounce = L21_1
L21_1 = "그러니까 마지막까지 저희 최선을 다 하는 거예요!"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "だから最後まで全力を尽くすのみです！"
L20_1.m_Talk_JPN = L21_1
L21_1 = "That's why we're going to do our best until the end!"
L20_1.m_Talk_ENG = L21_1
L21_1 = "所以我們要努力拚到最後一刻！"
L20_1.m_Talk_TWN = L21_1
L21_1 = "นั่นเป็นเหตุผลที่เราจะพยายามอย่างเต็มที่จนถึงที่สุด!"
L20_1.m_Talk_THA = L21_1
L21_1 = "Đó là lý do tại sao chúng ta sẽ cố gắng hết sức cho đến cuối cùng!"
L20_1.m_Talk_VTN = L21_1
L21_1 = "所以我们要尽全力到最后一刻！"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Deshalb werden wir bis zum Ende unser Bestes geben!"
L20_1.m_Talk_DEU = L21_1
L21_1 = "C'est pourquoi nous allons faire de notre mieux jusqu'à la fin !"
L20_1.m_Talk_FRA = L21_1
