L23_1.m_CharStrID = "FELICETTE_CANARY_NULL_NULL"
L23_1.m_Pos = "C"
L23_1.m_Crash = 10
L24_1 = "……맞는 말이네요."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "……そうですね。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "...You're right."
L23_1.m_Talk_ENG = L24_1
L24_1 = "……你說得對。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "...คุณพูดถูก"
L23_1.m_Talk_THA = L24_1
L24_1 = "…Đúng thế."
L23_1.m_Talk_VTN = L24_1
L24_1 = "……你说得对。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "... Du hast recht."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Vous avez raison..."
