L25_1 = "CHARADE2_ACT4_INTERLUDE1@74#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 74
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 5700401
L24_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "FELICETTE_CANARY_NULL_NULL"
L24_1.m_Pos = "C"
L25_1 = "아, 그리고 지금 와서 훈련 강도를 높일 생각은 없어요."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "あ、それから、今更訓練の強度を上げるつもりはありません。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Oh, and I don't intend on increasing our training intensity, by the way."
L24_1.m_Talk_ENG = L25_1
L25_1 = "還有，我不想現在才提高訓練強度。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "โอ้ ฉันไม่ได้ตั้งใจจะเพิ่มความเข้มข้นในการฝึกฝนของเรานะ"
L24_1.m_Talk_THA = L25_1
L25_1 = "Ồ, nhân tiện, tôi không có ý định tăng cường độ luyện tập."
L24_1.m_Talk_VTN = L25_1
L25_1 = "啊，还有，我打算提高训练强度了。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Oh, und ich habe übrigens nicht vor, unsere Trainingsintensität zu erhöhen."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Oh, et je n'ai pas l'intention d'augmenter l'intensité de notre entraînement, d'ailleurs."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "CHARADE2_ACT4_INTERLUDE1@75#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 75
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 5700401
L25_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "FELICETTE_CANARY_NULL_NULL"
L25_1.m_Pos = "C"
L26_1 = "결승까지 얼마 남지 않았어요. 두 사람도 컨디션 유지에 신경 써 주세요."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "決勝まであと少ししかないですし、二人とも調子を崩さないように気を付けてくださいね。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "The finals are just around the corner, and you two should maintain your best conditions."
L25_1.m_Talk_ENG = L26_1
L26_1 = "距離決賽沒剩多少時間，你們二個要留意自己的狀態。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "รอบชิงชนะเลิศอยู่ใกล้แค่เอื้อมแล้ว และคุณทั้งสองควรรักษาสภาพที่ดีที่สุดเอาไว้"
L25_1.m_Talk_THA = L26_1
L26_1 = "Trận chung kết sắp đến gần và hai người nên duy trì thể trạng tốt nhất."
L25_1.m_Talk_VTN = L26_1
L26_1 = "离决赛没剩多久了，你们要留意自己的状态。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Das Finale steht vor der Tür und ihr beide solltet in Topform bleiben."
L25_1.m_Talk_DEU = L26_1
L26_1 = "La finale est à nos portes, alors vous devriez rester en forme."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "CHARADE2_ACT4_INTERLUDE1@76#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 76
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 5700401
L26_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "FELICETTE_CANARY_NULL_NULL"
L26_1.m_Pos = "C"
L27_1 = "그럼, 전 대기실에서 잠깐 눈 좀 붙이고 올게요."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "では、私は楽屋に戻って少し仮眠を取ってきます。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Then, I'll be in the waiting room, getting some shuteye."
L26_1.m_Talk_ENG = L27_1
L27_1 = "那我先去休息室瞇一下。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "งั้นฉันก็จะอยู่ในห้องรอและกำลังหลับตาอยู่"
L26_1.m_Talk_THA = L27_1
L27_1 = "Thế tôi sẽ ở trong phòng chờ, chợp mắt một chút."
L26_1.m_Talk_VTN = L27_1
L27_1 = "那我去休息室小睡一会儿。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Also dann, ich werde im Wartezimmer kurz die Augen zumachen."
L26_1.m_Talk_DEU = L27_1
L27_1 = "En attendant, je serai dans la salle d'attente. J'ai besoin d'une petite sieste."
L26_1.m_Talk_FRA = L27_1
