L30_1 = "CHARADE2_ACT4_INTERLUDE1@79#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 5700401
L29_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "UNIT_IDLE"
L29_1.m_Face = L30_1
L29_1.m_CharStrID = "INTERN_FENRIR_NULL_NULL"
L29_1.m_Pos = "R"
L30_1 = "펠리세트, 어쩐지 분위기가 차분해진 것 같지 않나요?"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "フェリセット、なんだか落ち着いているように見えませんか？"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Is it just me or has Félicette gotten calmer these days?"
L29_1.m_Talk_ENG = L30_1
L30_1 = "你不覺得費莉塞特好像變得沒那麼易怒嗎？"
L29_1.m_Talk_TWN = L30_1
L30_1 = "เป็นแค่ฉันหรือเฟลิเซ็ตต์เริ่มสงบลงแล้ว?"
L29_1.m_Talk_THA = L30_1
L30_1 = "Có phải mình tôi thấy thế hay Félicette dạo này đã bình tĩnh hơn rồi?"
L29_1.m_Talk_VTN = L30_1
L30_1 = "你不觉得菲利塞特的气质变得冷静了吗？"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Bilde ich mir das nur ein oder ist Felicette entspannter geworden?"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Est-ce juste moi ou Felicette s'est assagie ces jours-ci ?"
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "CHARADE2_ACT4_INTERLUDE1@80#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 80
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 5700401
L30_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
