L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "INTERN_FENRIR_NULL_NULL"
L30_1.m_Pos = "R"
L31_1 = "평소였다면……."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "いつもなら……"
L30_1.m_Talk_JPN = L31_1
L31_1 = "If it were the usual Félicette, she'd be like..."
L30_1.m_Talk_ENG = L31_1
L31_1 = "要是平常……"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ถ้าเป็นเฟลิเซ็ตต์ปกติ เธอคงเป็น..."
L30_1.m_Talk_THA = L31_1
L31_1 = "Nếu là Félicette thường lệ, thì.."
L30_1.m_Talk_VTN = L31_1
L31_1 = "如果是平日里……"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Normalerweise hätte sie ..."
L30_1.m_Talk_DEU = L31_1
L31_1 = "D'habitude elle est plutôt du genre..."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "CHARADE2_ACT4_INTERLUDE1@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 5700401
L31_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "UNIT_SERIOUS"
L31_1.m_Face = L32_1
L31_1.m_CharStrID = "INTERN_FENRIR_NULL_NULL"
L31_1.m_Pos = "R"
L31_1.m_Crash = 20
L32_1 = "노엘! 고작 촬영 몇 개 했다고 헥─! 헥─! 거리면 어떡해요! 운동장 10바퀴 추가에요!"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "ノエル！　何本か撮影しただけでひいひい言うんじゃありません！　グラウンド10周追加！"
L31_1.m_Talk_JPN = L32_1
L32_1 = "\"Noelle! How can you be exhausted after shooting a couple of commercials?! I'm adding 10 more laps to your training routine!\""
L31_1.m_Talk_ENG = L32_1
L32_1 = "洛艾兒！才拍幾個廣告就喘成那樣！再給我再跑十圈！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "\"โนเอล! ถ่ายโฆษณา 2-3 เรื่อง ถ่ายโฆษณามาจะเหนื่อยได้ยังไง! ฉันเพิ่มรอบการฝึกซ้อมของคุณอีก 10 รอบ!\""
L31_1.m_Talk_THA = L32_1
L32_1 = "\"Noelle! Sao cô có thể kiệt sức sau khi mới quay vài quảng cáo?! Tôi sẽ thêm 10 vòng nữa vào lịch tập luyện!\""
L31_1.m_Talk_VTN = L32_1
L32_1 = "诺艾尔！怎么才拍了几个广告就喘成这个样子！给我再跑十圈！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "„Noelle! Wie kannst du schon so erschöpft sein, nachdem du nur ein paar Werbespots gedreht hast?! Lauf noch 10 Extrarunden um den Platz!“"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Noelle ! Comment pouvez-vous être déjà épuisée après avoir tourné quelques publicités ?! Vous me ferez 10 tours supplémentaires lors de votre entraînement !"
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "CHARADE2_ACT4_INTERLUDE1@82#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 82
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 5700401
L32_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_PRIDE"
L32_1.m_CharStrID = "INTERN_FENRIR_NULL_NULL"
L32_1.m_Pos = "R"
L33_1 = "……라고 했을 것 같은데."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "……って言われてたと思うんですけど。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "...That'd be more like her."
L32_1.m_Talk_ENG = L33_1
L33_1 = "……這才是正常的她吧？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "...นั่นคงจะเหมือนกับเธอมากกว่า"
L32_1.m_Talk_THA = L33_1
L33_1 = "...Như thế sẽ giống nhóc ấy hơn."
L32_1.m_Talk_VTN = L33_1
L33_1 = "……应该会这么说吧。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "... gesagt."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Voilà ce qu'elle aurait dit..."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "CHARADE2_ACT4_INTERLUDE1@83#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 5700401
L33_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_DESPAIR"
L33_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L33_1.m_Pos = "L"
L33_1.m_Crash = 10
L34_1 = "사춘기 꼬맹이 속을 내가 어떻게 알겠냐."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "思春期のガキの気持ちなんかわかんないよ。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "No one knows what goes on inside the mind of an adolescent kid."
L33_1.m_Talk_ENG = L34_1
L34_1 = "青春期的小鬼我不懂啦。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ไม่มีใครรู้ว่าเกิดอะไรขึ้นในใจของเด็กวัยรุ่น"
L33_1.m_Talk_THA = L34_1
L34_1 = "Không ai biết được điều gì đang diễn ra trong tâm trí của đứa trẻ vị thành niên."
L33_1.m_Talk_VTN = L34_1
L34_1 = "我怎么会明白青春期小鬼的心思呢。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Niemand weiß, was im Kopf eines heranwachsenden Kindes vorgeht."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Personne ne sait ce qui se passe dans la tête d'un pré-adolescent."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "CHARADE2_ACT4_INTERLUDE1@84#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 84
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 5700401
L34_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "UNIT_IDLE"
L34_1.m_Face = L35_1
L34_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L34_1.m_Pos = "L"
L35_1 = "그동안 코치랑 있으면서 쟤도 뭔가 느낀 게 있었나 보지."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "しばらくコーチといて、何か気持ちに変化があったんじゃないの。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Maybe she's realized something while spending time with our coach."
L34_1.m_Talk_ENG = L35_1
L35_1 = "可能是這段時間和教練一起相處，她有感受到什麼吧？"
