L49_1 = "오늘은 보자마자 소리지르면서 달려들지는 않네?"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "今日はいきなり叫びながら襲い掛かってきたりしないのね？"
L48_1.m_Talk_JPN = L49_1
L49_1 = "I see you're not screaming and running at me like last time."
L48_1.m_Talk_ENG = L49_1
L49_1 = "今天怎麼沒有一看到我就大吼大叫撲上來？"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ฉันเห็นคุณไม่กรีดร้องและวิ่งมาหาฉันเหมือนครั้งที่แล้ว"
L48_1.m_Talk_THA = L49_1
L49_1 = "Tôi thấy nhóc không la hét và chạy tới tôi như lần trước nữa."
L48_1.m_Talk_VTN = L49_1
L49_1 = "今天怎么不是一看到我就大喊大叫冲上来了？"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Du rennst ja heute nicht schreiend auf mich zu, sobald du mich siehst."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Je vois que tu ne cries pas et ne me fonces pas dessus comme l'autre fois."
L48_1.m_Talk_FRA = L49_1
