L49_1[L50_1] = true
L50_1 = "그 사이에 어른스러워졌네. 좋은 후견인을 만나서 그런 걸까나?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "見ないうちに大人になったわね。良い後見人に出逢えたからかしら？"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Seems like you've matured a little. Is it because you met yourself a good supporter?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "這期間變成熟不少呢，是因為遇到好的監護人嗎？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ดูเหมือนคุณจะเป็นผู้ใหญ่ขึ้นนิดหน่อย เป็นเพราะคุณได้พบกับผู้สนับสนุนที่ดีหรือเปล่า?"
L49_1.m_Talk_THA = L50_1
L50_1 = "Có vẻ như nhóc đã trưởng thành hơn một chút. Có phải vì nhóc đã gặp được người hỗ trợ tốt không?"
L49_1.m_Talk_VTN = L50_1
L50_1 = "这段时间稳重了不少，是因为遇到了好的监护人吗？"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Sieht so aus, als wärst du etwas reifer geworden. Liegt es daran, dass du einen guten Unterstützer kennengelernt hast?"
L49_1.m_Talk_DEU = L50_1
L50_1 = "On dirait que tu as un peu mûri. Serait-ce parce que tu as rencontré un bon tuteur ?"
L49_1.m_Talk_FRA = L50_1
