L2_1 = "그러니까…… 당신을 때려 죽이는 건, 모두가 지켜보는 결승전에서예요."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "だからその通り……あなたを殴り殺すのは、決勝戦のみんなが見ている前でやります。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "So... beating you up will have to be done in the finals for everyone to see."
L1_1.m_Talk_ENG = L2_1
L2_1 = "我……我要在眾所矚目的決賽中殺了你。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ดังนั้น...การทุบตีคุณจะต้องทำให้ถึงรอบชิงชนะเลิศให้ทุกคนได้เห็น"
L1_1.m_Talk_THA = L2_1
L2_1 = "Vậy nên... việc đánh bại cô sẽ phải được thực hiện trong trận chung kết cho mọi người cùng xem."
L1_1.m_Talk_VTN = L2_1
L2_1 = "所以……我会在所有人都注视的决赛中把你杀死。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Also ... Sie zu Tode zu prügeln, muss ich mir bis zum Finale aufheben, damit es jeder sehen kann."
L1_1.m_Talk_DEU = L2_1
L2_1 = "C'est pourquoi... Je dois vous battre en finale afin que tout le monde puisse le voir."
L1_1.m_Talk_FRA = L2_1
