L5_1 = "글쎄? 그런 태도는 너무 식상한 걸?"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "どうかしら？　あの態度は少し陳腐だったんじゃないかしらね？"
L4_1.m_Talk_JPN = L5_1
L5_1 = "But I dunno. Your attitude was a little dull for my taste."
