L5_1 = "不過，好像有點太老套？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "แต่ฉันไม่รู้ ทัศนคติของคุณค่อนข้างน่าเบื่อสำหรับรสนิยมของฉัน"
L4_1.m_Talk_THA = L5_1
L5_1 = "Nhưng tôi không biết. Thái độ của nhóc hơi buồn tẻ đối với sở thích của tôi."
L4_1.m_Talk_VTN = L5_1
L5_1 = "不过，那种态度也太老套了吧？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Aber ... deine Haltung war für meinen Geschmack viel zu öde."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Mais je ne sais pas... Ton attitude était un peu terne à mon goût."
