L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "どうせ暴露するんだったら、あなたの両親のことも話せばよかったじゃない。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "If you were going to go big, why didn't you mention your parents in it?"
L5_1.m_Talk_ENG = L6_1
L6_1 = "既然想大鬧一場，你何不乾脆說出你父母的事。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "หากคุณกำลังจะไปใหญ่ทำไมคุณไม่พูดถึงพ่อแม่ของคุณในนั้น?"
L5_1.m_Talk_THA = L6_1
L6_1 = "Nếu định làm lớn, tại sao nhóc không nhắc đến bố mẹ mình trong đó?"
L5_1.m_Talk_VTN = L6_1
L6_1 = "既然想干一场大的，为什么不说说你父母的事呢？"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Wenn du viel Aufmerksamkeit erregen wolltest, hättest du zumindest deine Eltern zur Sprache bringen sollen."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Si tu voulais faire grand, pourquoi ne pas avoir mentionné tes parents ?"
