L8_1 = "だから私を倒して無罪を証明したい。そうよね？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "And that's why you want to defeat me and prove they're not guilty to the whole world."
L7_1.m_Talk_ENG = L8_1
L8_1 = "所以你才想打敗我證明你父母的清白。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "และนั่นคือสาเหตุว่าทำไมคุณถึงอยากเอาชนะฉัน และพิสูจน์ว่าพวกเขาไม่มีความผิดต่อคนทั้งโลก"
L7_1.m_Talk_THA = L8_1
L8_1 = "Và đó là lý do tại sao nhóc muốn đánh bại tôi và chứng minh rằng họ vô tội trước cả thế giới."
L7_1.m_Talk_VTN = L8_1
L8_1 = "所以你才想打败我，然后证明他们无罪？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Und deshalb willst du mich besiegen und der ganzen Welt beweisen, dass sie unschuldig sind."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Et c'est pourquoi tu veux me vaincre et prouver au monde entier qu'ils ne sont pas coupables."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
