L9_1 = "전혀요. 바보 같은 착각 마세요."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "いいえ。馬鹿馬鹿しい勘違いはやめてください。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Not at all. Don't be stupid."
L8_1.m_Talk_ENG = L9_1
L9_1 = "根本不是這樣，你少自以為是。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ไม่เลย อย่าโง่เลย"
L8_1.m_Talk_THA = L9_1
L9_1 = "Không có gì. Đừng ngu ngốc thế.."
L8_1.m_Talk_VTN = L9_1
L9_1 = "根本不是，你别自以为是了。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Nein. Machen Sie sich nicht lächerlich."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Pas du tout. Ne soyez pas stupide."
