L9_1.m_Crash = 20
L10_1 = "바람난 엄마나, 책임감 없이 나 혼자 두고 죽어버린 아빠 같은 건 아무래도 좋아."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "浮気したママだとか、無責任に私一人を残して死んだパパなんてどうでもいいです。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "I don't really care about my cheating mother or my irresponsible father who killed himself and left me all alone."
L9_1.m_Talk_ENG = L10_1
L10_1 = "無論是出軌的媽媽，還是不負責任丟下我一個人死去的爸爸，我都無所謂。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ฉันไม่สนใจแม่นอกใจหรือพ่อที่ไม่รับผิดชอบที่ฆ่าตัวตายและทิ้งฉันไว้ตามลำพัง"
L9_1.m_Talk_THA = L10_1
L10_1 = "Tôi thực sự không quan tâm đến người mẹ lừa dối hay người cha vô trách nhiệm đã tự sát và bỏ mặc tôi một mình."
L9_1.m_Talk_VTN = L10_1
L10_1 = "我现在不关心他们，无论是出轨的母亲，还是毫无责任感留下我独自一人的父亲，都无所谓。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Ich interessiere mich weder für meine untreue Mutter noch für meinen verantwortungslosen Vater, der sich umgebracht und mich ganz allein gelassen hat."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Je ne me soucie pas vraiment de ma mère infidèle ou de mon père irresponsable qui s'est suicidé et m'a laissée toute seule."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
