L11_1 = "m_bCharPinup"
L10_1[L11_1] = true
L11_1 = "저는 제 인생을 망친 인간들에게 대가를 치르게 하고 싶을 뿐이에요."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "私はただ、私の人生をめちゃくちゃにした奴らに復讐したいだけです。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "All I want is for those who ruined my life to pay for what they did."
L10_1.m_Talk_ENG = L11_1
L11_1 = "我只是想讓毀掉我人生的人付出代價而已。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ทั้งหมดที่ฉันต้องการคือให้คนที่ทำลายชีวิตฉันชดใช้สิ่งที่พวกเขาทำ"
L10_1.m_Talk_THA = L11_1
L11_1 = "Tất cả những gì tôi muốn là những kẻ đã hủy hoại cuộc đời tôi phải trả giá cho những gì chúng đã làm."
L10_1.m_Talk_VTN = L11_1
L11_1 = "我只是想让毁掉我生活的人付出代价而已。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Ich will nur, dass diejenigen, die mein Leben ruiniert haben, für das bezahlen, was sie mir angetan haben."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Tout ce que je veux, c'est que ceux qui ont ruiné ma vie payent pour ce qu'ils ont fait."
L10_1.m_Talk_FRA = L11_1
