L11_1.m_Crash = 10
L12_1 = "그러니까 기대하세요. 당신은 그 인간들 대표거든요."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "だから楽しみにしていてください。あなたはその代表格ですから。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "So, I hope you look forward to it as well. Because you represent all of them."
L11_1.m_Talk_ENG = L12_1
L12_1 = "所以你敬請期待吧，你就是那些人的代表。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ดังนั้นฉันหวังว่าคุณจะตั้งตารอเช่นกัน เพราะคุณเป็นตัวแทนของพวกเขาทั้งหมด"
L11_1.m_Talk_THA = L12_1
L12_1 = "Nên tôi hy vọng cô cũng mong chờ nó. Bởi vì cô đại diện cho tất cả bọn chúng."
L11_1.m_Talk_VTN = L12_1
L12_1 = "所以你期待着吧。你就是那些人的代表。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Sie können sich also darauf freuen. Denn Sie repräsentieren all diese Menschen."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Alors préparez-vous, car vous allez payer pour eux."
L11_1.m_Talk_FRA = L12_1
