L15_1[L16_1] = L17_1
L16_1 = "처음 봤을 때부터 네가 꽤 마음에 들었어, 루이즈 로랑생."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "最初見た時からあなたには一目置いていたの、ルイーズ・ローランサン。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "I knew I liked you from the first time we met, Louisé Laurencin."
L15_1.m_Talk_ENG = L16_1
L16_1 = "打從我第一眼看到你就蠻喜歡你的，露易絲·羅蘭桑。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ฉันรู้ว่าฉันชอบคุณตั้งแต่ครั้งแรกที่เราพบ หลุยส์ ลอเรนซิน"
L15_1.m_Talk_THA = L16_1
L16_1 = "Tôi biết ngay tôi thích nhóc ngay từ lần đầu chúng ta gặp nhau, Louisé Laurencin."
L15_1.m_Talk_VTN = L16_1
L16_1 = "我从看到你的第一眼起就挺喜欢你的，路易斯·罗兰珊。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Ich mochte dich bereits, als wir uns das erste Mal trafen, Louise Laurencin."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Je t'ai toujours appréciée, depuis le jour où nous nous sommes rencontrées, Louise Laurencin."
L15_1.m_Talk_FRA = L16_1
