L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "あなたのような芸術家タイプの人間は、どんなことがあっても諦めることがない。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "People with artistic tendencies, like you, never give up."
L16_1.m_Talk_ENG = L17_1
L17_1 = "像你這種偏藝術家性格的傢伙，無論發生什麼事都不會放棄。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ผู้มีแนวโน้มด้านศิลปะเช่นคุณไม่เคยยอมแพ้"
L16_1.m_Talk_THA = L17_1
L17_1 = "Người có thiên hướng nghệ thuật như nhóc thì không bao giờ bỏ cuộc."
L16_1.m_Talk_VTN = L17_1
L17_1 = "像你这样有着艺术家性格的家伙，无论发生什么事都不会放弃。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Menschen mit künstlerischen Neigungen wie du geben niemals auf."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Les personnes avec un côté artistique, comme toi, n'abandonnent jamais."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
