L18_1 = "m_CharScaleTime"
L19_1 = 0.01
L17_1[L18_1] = L19_1
L18_1 = "아무리 방해하고, 짓밟아도 마지막까지 꺾이지 않고 독기를 머금지."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "どんなに妨害して、踏みにじっても最後まで折れずに牙を向けてくる。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Others may try to stop you or stomp on you, but you endure it and never break."
L17_1.m_Talk_ENG = L18_1
L18_1 = "不管怎麼妨礙你、怎麼踐踏你，你都會帶著一股狠勁，直到最後一刻也不放棄。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "คนอื่นอาจพยายามหยุดคุณหรือกระทืบคุณ แต่คุณอดทนและไม่เคยแตกหัก"
L17_1.m_Talk_THA = L18_1
L18_1 = "Người khác có thể cố gắng ngăn cản hoặc dẫm đạp lên nhóc, nhưng nhóc chịu đựng và không bao giờ gục ngã."
L17_1.m_Talk_VTN = L18_1
L18_1 = "无论怎么妨碍、怎么践踏，都会带着一股狠劲儿，直到最后一刻也不会放弃。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Ganz gleich, wie sehr andere auch versuchen, dich aufzuhalten oder auf dir herumzutrampeln, du hältst es aus und bleibst verbittert."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Les autres peuvent essayer de t'arrêter ou de te piétiner, mais tu tiens bon jusqu'au bout."
L17_1.m_Talk_FRA = L18_1
