L20_1.m_Crash = 10
L21_1 = "그래서…… 무너뜨릴 보람이 있는 거야."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "だからこそ……潰し甲斐がある。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "That's also why... I'll be relishing the moment I destroy you."
L20_1.m_Talk_ENG = L21_1
L21_1 = "所以……才有打敗的意義。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "นั่นเป็นเหตุผลว่าทำไม... ฉันจะเพลิดเพลินไปกับช่วงเวลาที่ฉันทำลายคุณ"
L20_1.m_Talk_THA = L21_1
L21_1 = "Đó cũng là lý do tại sao... tôi sẽ tận hưởng khoảnh khắc tiêu diệt nhóc."
L20_1.m_Talk_VTN = L21_1
L21_1 = "所以……我会很享受彻底毁掉你的那一刻。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Das ist auch der Grund ... warum ich den Moment genießen werde, in dem ich dich zerstöre."
L20_1.m_Talk_DEU = L21_1
L21_1 = "C'est aussi pourquoi... je savourerai le moment où je te détruirai."
L20_1.m_Talk_FRA = L21_1
