L22_1 = "m_CharScaleTime"
L23_1 = 0.01
L21_1[L22_1] = L23_1
L22_1 = "마치 몇 십년을 바라보고 공들여서 빚는 최고급 와인처럼 말이야."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "何十年も熟成させて作る最高級ワインのようなものよ。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Much like how the best wine takes decades to mature."
L21_1.m_Talk_ENG = L22_1
L22_1 = "就好像投入幾十年的心力釀成的最高級紅酒，"
L21_1.m_Talk_TWN = L22_1
L22_1 = "เช่นเดียวกับการที่ไวน์ที่ดีที่สุดต้องใช้เวลาหลายทศวรรษกว่าจะสุก"
L21_1.m_Talk_THA = L22_1
L22_1 = "Giống như loại rượu ngon nhất phải mất hàng thập kỷ để trưởng thành."
L21_1.m_Talk_VTN = L22_1
L22_1 = "就好像投入了数十年精力酿成的最高级红酒。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "So wie auch der beste Wein über mehrere Jahrzehnte hinweg mit größter Sorgfalt hergestellt wird."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Tout comme le meilleur vin met des décennies à mûrir."
L21_1.m_Talk_FRA = L22_1
