L22_1[L23_1] = L24_1
L23_1 = "m_CharScaleTime"
L24_1 = 0.01
L22_1[L23_1] = L24_1
L23_1 = "오랜 기다림 끝에 그 마개를 따고 맛과 향을 음미하는 건, 꽤나 각별한 경험이지."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "待ちに待ったその日、栓を抜いて味と香りを吟味するのはすごく格別な経験だもの。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "It's a unique experience to enjoy its aroma and taste after the long wait."
L22_1.m_Talk_ENG = L23_1
L23_1 = "經過漫長的等待後，打開蓋子品嘗味道，是一種非常特別的體驗。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ถือเป็นประสบการณ์ที่ไม่เหมือนใครในการเพลิดเพลิน\nไปกับกลิ่นหอมและรสชาติหลังจากการรอคอยอันยาวนาน"
L22_1.m_Talk_THA = L23_1
L23_1 = "Đó là một trải nghiệm độc nhất khi thưởng thức hương thơm và vị của nó sau một thời gian dài chờ đợi."
L22_1.m_Talk_VTN = L23_1
L23_1 = "在漫长的等待后，打开盖子品尝它的味道和香气，是一种非常特别的经历。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Ist es ein einzigartiges Erlebnis, nach dem langen Warten endlich seinen Verschluss zu öffnen, um sein Aroma und seinen Geschmack zu genießen."
L22_1.m_Talk_DEU = L23_1
L23_1 = "C'est une expérience unique que de profiter de son arôme et de son goût après cette longue attente."
L22_1.m_Talk_FRA = L23_1
