L25_1.m_Face = "UNIT_HATE"
L25_1.m_CharStrID = "FELICETTE_CANARY_NULL_NULL"
L25_1.m_Pos = "L"
L26_1 = "제정신이 아니네요."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "狂っていますね。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "You must be out of your mind."
L25_1.m_Talk_ENG = L26_1
L26_1 = "你真是有毛病。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "คุณคงจะเสียสติไปแล้ว"
L25_1.m_Talk_THA = L26_1
L26_1 = "Cô hẳn là điên rồi."
L25_1.m_Talk_VTN = L26_1
L26_1 = "你真是病得不轻。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Sie scheinen nicht ganz bei Verstand zu sein."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Vous avez vraiment perdu la tête."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "CHARADE2_ACT4_INTERLUDE1@126#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 126
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 5700401
L26_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "UNIT_IDLE"
L26_1.m_Face = L27_1
L26_1.m_CharStrID = "FELICETTE_CANARY_NULL_NULL"
L26_1.m_Pos = "L"
L27_1 = "아, 그러고보니 뉴스에서도 나왔죠? 요즘 약도 한다면서요?"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "ああ、そういえば最近はクスリもやっているってニュースに出ていましたね？"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Oh, I saw you were on the news. You're doing drugs these days?"
L26_1.m_Talk_ENG = L27_1
L27_1 = "對吼，新聞好像也報導過，說你最近有吸毒？"
L26_1.m_Talk_TWN = L27_1
L27_1 = "อ๋อ ฉันเห็นคุณอยู่ในข่าว ช่วงนี้คุณเสพยาเหรอ?"
L26_1.m_Talk_THA = L27_1
L27_1 = "Ồ, tôi thấy cô xuất hiện trên bản tin. Dạo này cô đang chơi ma túy à?"
L26_1.m_Talk_VTN = L27_1
L27_1 = "啊，对了，新闻上好像也说过，你最近还嗑药了是吗？"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Ach ja, Sie waren doch in den Nachrichten, oder? Ich habe gehört, dass Sie heutzutage Drogen nehmen."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Oh, j'ai vu ça dans les journaux. Il parait que vous prenez de la drogue ces jours-ci ?"
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "CHARADE2_ACT4_INTERLUDE1@127#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 127
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 5700401
L27_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "GOLD_CHARADE_NULL_NULL"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "R"
L28_1 = "뭐, 그 정도야 나 정도 되는 카운터에겐 불량식품 같은 거거든."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "まぁ、そんなの私ほどのカウンターになれば、駄菓子をたしなむ程度にしかならないわ。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Well, you can't really call them drugs when you're a Counter like me."
L27_1.m_Talk_ENG = L28_1
L28_1 = "對我這種水準的制裁者而言，那根本不是毒品，而是垃圾食物。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "คุณไม่สามารถเรียกมันว่ายาเสพติดได้จริงๆ เมื่อคุณเป็นเคาน์เตอร์เช่นฉัน"
L27_1.m_Talk_THA = L28_1
L28_1 = "Chà, nhóc thực sự không thể gọi chúng là ma túy nếu là một Counter như tôi."
L27_1.m_Talk_VTN = L28_1
L28_1 = "那点程度对我这样的制裁者来说，就像是垃圾食品。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Nun, man kann sie nicht wirklich Drogen nennen, wenn man ein Counter wie ich ist."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Eh bien, on ne peut pas vraiment appeler ça de la drogue quand on est un Counter comme moi."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "CHARADE2_ACT4_INTERLUDE1@128#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 128
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 5700401
L28_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "GOLD_CHARADE_NULL_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "R"
L29_1 = "중독의 위험성 같은 건, 너희 같은 평범한 인간이나 신경 쓸 일이지."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "中毒の危険性なんて、あなたのような平凡な人間が心配する類のものよ。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Addiction is only something that ordinary people, like you, worry about."
L28_1.m_Talk_ENG = L29_1
L29_1 = "吸毒會危害人體這種事，是像你們這種普通人才需要擔心。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "การเสพติดเป็นเพียงสิ่งที่คนธรรมดาเช่นคุณกังวลเท่านั้น"
L28_1.m_Talk_THA = L29_1
L29_1 = "Nghiện ngập chỉ là điều mà những người bình thường như nhóc lo lắng."
L28_1.m_Talk_VTN = L29_1
L29_1 = "上瘾什么的，是你们这种平凡人才会担心的事情。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Die Risiken einer Sucht sind etwas, worüber sich nur gewöhnliche Menschen wie du Sorgen machen müssen."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Seuls les gens ordinaires, comme toi, s'inquiètent des addictions."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
