L30_1[L31_1] = L32_1
L30_1.m_Crash = 10
L31_1 = "그래요? 다른 사람들도 그렇게 생각할까요?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "ふうん？　果たして他のみんなもそう思うでしょうか？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Is that so? You think the public will feel the same way?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "是嗎？其他人也是這麼想的嗎？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เป็นอย่างนั้นเหรอ? คุณคิดว่าประชาชนจะรู้สึกแบบเดียวกันหรือไม่?"
L30_1.m_Talk_THA = L31_1
L31_1 = "Là vậy sao? Cô nghĩ công chúng sẽ cảm thấy như vậy?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "是吗？你确定其他人也是这么想的？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ist das so? Glauben Sie, dass die Öffentlichkeit genauso denken wird?"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Ah bon ? Vous pensez que le public ressentira la même chose ?"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
