L33_1[2] = L35_1
L31_1[L32_1] = L33_1
L32_1 = "m_CharScaleTime"
L33_1 = 0.01
L31_1[L32_1] = L33_1
L32_1 = "약물 중독자 챔피언이 평범한 인간에게 뒈지면, 반응이 어떨지 궁금하네요."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "薬物中毒者のチャンピオンが平凡な人間に負けたら、どんな反響があるか楽しみですね。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "It'll be fun to see their reaction when an ordinary person defeats a junkie champion."
L31_1.m_Talk_ENG = L32_1
L32_1 = "癮君子冠軍如果栽到普通人的手裡，我很好奇大家的反應會如何。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "คงจะสนุกดีที่ได้เห็นปฏิกิริยาของพวกเขาเมื่อคนธรรมดาสามารถเอาชนะแชมป์เปี้ยนขี้ยาได้"
L31_1.m_Talk_THA = L32_1
L32_1 = "Sẽ rất vui khi thấy phản ứng của họ khi một người bình thường đánh bại một nhà vô địch nghiện ngập."
L31_1.m_Talk_VTN = L32_1
L32_1 = "瘾君子冠军被普通人打败，我很好奇大家的反应。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Es wird lustig sein, ihre Reaktion zu sehen, wenn ein gewöhnlicher Mensch wie ich einen Drogenjunkie-Champion wie Sie besiegt."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Je me demande comment ils réagiront quand ils verront une personne ordinaire battre une championne toxicomane."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
