L32_1[L33_1] = L34_1
L33_1 = "m_CharScaleTime"
L34_1 = 0.01
L32_1[L33_1] = L34_1
L33_1 = "그 잘난 낯짝이 얼마나 흉하게 일그러질지도."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "その偉そうな面が、どれほど醜く歪むかも。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "How that smug face of yours will be hideously distorted."
L32_1.m_Talk_ENG = L33_1
L33_1 = "還有，你那副囂張的嘴臉又會變得多難看。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ใบหน้าที่เย่อหยิ่งของคุณจะถูกบิดเบือนอย่างน่าสยดสยอง"
L32_1.m_Talk_THA = L33_1
L33_1 = "Khuôn mặt tự mãn đó của cô sẽ bị biến dạng một cách gớm ghiếc như thế nào."
L32_1.m_Talk_VTN = L33_1
L33_1 = "还有，你那副自以为是的嘴脸又会扭曲得多么难看。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Wie hässlich wird Ihr arrogantes Gesicht wohl aussehen, wenn es vor Wut ganz verzerrt ist?"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Quand ils verront la monstruosité derrière ce joli visage."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
