L35_1 = "CHARADE2_ACT4_INTERLUDE1@134#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 5700401
L34_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "UNIT_IDLE"
L34_1.m_Face = L35_1
L34_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_02"
L35_1 = "GOLD_CHARADE_NULL_NULL"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "C"
L35_1 = "그래. 어디 한 번 기어올라와 봐, 루이즈. 정상에서 기다리고 있을 테니까."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "いいわ。這い上がってきてみなさい、ルイーズ。頂上で待っているわ。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Yeah. Let's see you try, Louisé. I'll be waiting for you at the top."
L34_1.m_Talk_ENG = L35_1
L35_1 = "很好，你努力往上爬吧，露易絲。我會在山頂等你。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ใช่ ลองดูคุณหลุยส์ ฉันจะรอคุณอยู่ที่ด้านบน"
L34_1.m_Talk_THA = L35_1
L35_1 = "Yeah. Thử xem nào, Louisé. Tôi sẽ đợi nhóc ở trên đỉnh."
L34_1.m_Talk_VTN = L35_1
L35_1 = "很好，你尽管试着爬上来吧，路易斯。我会在顶峰等着你。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Ja. Versuch es ruhig, Louise. Ich werde oben auf dich warten."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Eh bien, tu peux toujours essayer, Louise. Je t'attendrai au sommet."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "CHARADE2_ACT4_INTERLUDE1@135#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 135
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 5700401
L35_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_Face = "UNIT_DESPAIR"
L36_1 = "GOLD_CHARADE_NULL_NULL"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "C"
L35_1.m_Crash = 10
L36_1 = "하지만 트래시토킹은 아직 더 배워야겠다. 강한 부정은 긍정이야."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "でも、トラッシュトークはもう少し磨いた方がよさそうね。強い否定は肯定になっちゃうわよ。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "But you should work on your trash-talking skills. A strong denial just means affirmation, you know?"
L35_1.m_Talk_ENG = L36_1
L36_1 = "不過，損人的話還是要多學學。強烈的否定就是肯定。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "แต่คุณควรฝึกทักษะการพูดไร้สาระ การปฏิเสธที่รุนแรงหมายถึงการยืนยัน คุณรู้ไหม?"
L35_1.m_Talk_THA = L36_1
L36_1 = "Nhưng nhóc nên luyện kỹ năng nói bẩn thỉu. Từ chối thẳng thừng chỉ có nghĩa là khẳng định, biết không?"
L35_1.m_Talk_VTN = L36_1
L36_1 = "不过，损人的话还是要多学学。强烈的否定就是肯定，你知道的吧？"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Aber du solltest mehr an deiner Wortwahl arbeiten. Eine so starke Ablehnung bestätigt schließlich nur, dass ich recht habe."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Mais tu devrais vraiment améliorer tes insultes. Nier les choses est souvent la preuve de leur véracité."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
