L42_1 = "아직…… 아직 모르고 있는 눈치야. 비장의 수단은 들키지 않았어."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "まだ……まだ気づかれていない様子だった。切り札はまだバレていない。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "She... She still doesn't know. She doesn't know about my ace up my sleeve."
L41_1.m_Talk_ENG = L42_1
L42_1 = "她……好像還沒發現，沒發現我的絕招。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "เธอ...เธอยังคงไม่รู้ เธอไม่รู้เกี่ยวกับความเก่งของฉันเลย"
L41_1.m_Talk_THA = L42_1
L42_1 = "Cô ta... Cô ta vẫn chưa biết, về con át chủ bài của mình."
L41_1.m_Talk_VTN = L42_1
L42_1 = "好像……好像还没发现。杀手锏没有被看出来。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Sie ... Sie weiß es immer noch nicht. Sie weiß nichts von meinem Ass im Ärmel."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Elle... elle ne sait toujours pas. Elle ne sait pas pour l'atout dans ma manche."
L41_1.m_Talk_FRA = L42_1
