L44_1 = "必须把奥兹曼迪亚斯给……"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Damit werde ich endlich in der Lage sein, Ozymandias ..."
L43_1.m_Talk_DEU = L44_1
