L48_1 = "CHARADE2_ACT4_INTERLUDE1@147#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 147
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 5700401
L47_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L48_1 = "시니어를 만나러 가신 분이 제 동의도 없이, 현지에서 직원들을 고용한 것도 모자라서……."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "シニアとの交渉に出かけて行ったはずが、私に何の相談もせずに現地で社員を採用したばかりか……"
L47_1.m_Talk_JPN = L48_1
L48_1 = "You said you were going to meet the Senior of Charade. But not only did you go hire new employees, and without asking me first, by the way..."
L47_1.m_Talk_ENG = L48_1
L48_1 = "明明是去見Senior的，結果竟然沒經過我的同意，就在當地雇用員工……"
L47_1.m_Talk_TWN = L48_1
L48_1 = "คุณบอกว่าคุณกำลังจะไปพบผู้อาวุโสของชาเรดแต่ไม่เพียงแต่คุณไปจ้างพนักงานใหม่ และโดยไม่ถามฉันก่อน อีกอย่าง..."
L47_1.m_Talk_THA = L48_1
L48_1 = "Ngài nói sẽ gặp Thành Viên Cấp Cao of Charade. Nhưng ngài không chỉ đi thuê nhân viên mới mà còn không hỏi ý kiến tôi trước nữa..."
L47_1.m_Talk_VTN = L48_1
L48_1 = "老板，您在没经过我同意的情况下，在当地雇佣职员就算了……"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Sie sagten, Sie würden nach Charade gehen, um dort den Senior zu treffen. Aber Sie haben nicht nur neue Mitarbeiter eingestellt, ohne mich vorher zu fragen ..."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Vous avez dit que vous alliez rencontrer le Senior de Charade. Mais non seulement vous êtes allé embaucher de nouveaux employés, sans me demander d'abord, soit dit-en passant..."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "CHARADE2_ACT4_INTERLUDE1@148#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 148
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 5700401
L48_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = "회사 명의로, 건틀렛 리그에 나가 결승전까지 올라가셨다고요."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "会社名義で、ガントレットリーグに出場し、決勝戦まで進出。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "You also used the company name to enter in the Gauntlet League and made it to the finals."
L48_1.m_Talk_ENG = L49_1
L49_1 = "接著還用公司的名義參加聖鎧聯賽，然後還進入決賽？"
L48_1.m_Talk_TWN = L49_1
L49_1 = "คุณยังใช้ชื่อบริษัทเพื่อเข้าสู่ลีกกอนต์เล็ต และผ่านเข้าสู่รอบชิงชนะเลิศ"
L48_1.m_Talk_THA = L49_1
L49_1 = "Ngài cũng đã sử dụng tên công ty để tham gia Gauntlet League và lọt vào vòng chung kết."
L48_1.m_Talk_VTN = L49_1
L49_1 = "竟然还用公司的名义参加圣铠，并且还进入了决赛。没记错的话，您明明只是去见一趟资深管理者？"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Sondern Sie haben auch den Namen des Unternehmens verwendet, um an der Fehde-Liga teilzunehmen und es bis ins Finale geschafft."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Mais vous avez également utilisé le nom de l'entreprise pour participer à la Compétition et vous êtes arrivé en finale."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "CHARADE2_ACT4_INTERLUDE1@149#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 149
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 5700401
L49_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_Face = "UNIT_PRIDE"
L50_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L49_1.m_CharStrID = L50_1
L49_1.m_Pos = "C"
L50_1 = "참 축하할 일이죠. 좋아하는 사람들이 어찌나 많은지 익명의 협박 메일들이 회사로 쏟아져 들어오더군요."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "大変おめでたいことですね。応援してくださる方々がたくさんいらっしゃるようで、会社宛てに脅迫メールが山ほど来ていますよ。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Well, this is great news. So much so that people are congratulating us by sending piles and piles of anonymous mail threats."
L49_1.m_Talk_ENG = L50_1
L50_1 = "真是可喜可賀呢，應該很多人喜歡你們吧？匿名的恐嚇信如雪片般飛來呢。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "นี่เป็นข่าวดี มากเสียจนผู้คนแสดงความยินดีกับเราด้วย\nการส่งภัยคุกคามทางไปรษณีย์ที่ไม่ระบุตัวตนจำนวนมาก"
L49_1.m_Talk_THA = L50_1
L50_1 = "Vâng, đây là tin tuyệt vời. Đến mức tất cả đang chúc mừng chúng ta bằng cách gửi hàng đống thư đe dọa nặc danh."
L49_1.m_Talk_VTN = L50_1
L50_1 = "很好，恭喜啊。公司收到的匿名威胁邮件不断，看来大家都很喜欢你们。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Nun, das sind eigentlich großartige Neuigkeiten. Es gefiel sogar so vielen Menschen, dass sie uns mit massenweise anonymen Drohungen per Mail überhäuft haben."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Eh bien, c'est une excellente nouvelle. À tel point que les gens nous félicitent et nous envoient des tas et des tas de courriers de menace anonymes."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "CHARADE2_ACT4_INTERLUDE1@150#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 150
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 5700401
L50_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "C"
L50_1.m_Crash = 10
L51_1 = "그래서? 회사차원에서 축하라도 해드릴까요?"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "それで？　会社をあげてお祝いでもすればよろしいのでしょうか？"
L50_1.m_Talk_JPN = L51_1
L51_1 = "So? Would you like a congratulations from the company?"
L50_1.m_Talk_ENG = L51_1
L51_1 = "所以呢？我要站在公司的立場恭喜你嗎？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ดังนั้น? คุณต้องการคำแสดงความยินดีจากบริษัทหรือไม่?"
L50_1.m_Talk_THA = L51_1
L51_1 = "Thế? Ngài có muốn nhận được lời chúc mừng từ công ty không?"
L50_1.m_Talk_VTN = L51_1
L51_1 = "我要不要也站在公司的立场祝贺一下你们？"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Also? Möchten Sie, dass das Unternehmen Ihnen ebenfalls gratuliert?"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Alors ? Souhaitez-vous des félicitations de la part de l'entreprise ?"
L50_1.m_Talk_FRA = L51_1
