L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "C"
L1_1.m_Crash = 10
L2_1 = "아쉽게도 본사가 파괴돼서 플랜카드는 못 걸겠지만."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "大変残念ですが本社が崩壊しておりますので、垂れ幕は無理そうですね。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "It's a shame that we can't put up a banner due to our main office getting destroyed."
L1_1.m_Talk_ENG = L2_1
L2_1 = "只可惜總公司已經變得跟廢墟一樣，無法掛上祝賀布條。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "น่าเสียดายที่เราไม่สามารถติดแบนเนอร์ได้เนื่องจากสำนักงานใหญ่ของเราถูกทำลาย"
L1_1.m_Talk_THA = L2_1
L2_1 = "Thật tiếc khi chúng ta không thể treo biểu ngữ do văn phòng chính của chúng ta đã bị phá hủy."
L1_1.m_Talk_VTN = L2_1
L2_1 = "可惜总公司没了，没法给你们挂个横幅。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Es ist eine Schande, dass wir aufgrund der Zerstörung unseres Hauptquartiers keine Plakate aufhängen können."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Quel dommage que nous ne puissions pas accrocher de bannière en raison de la destruction de notre bureau principal."
L1_1.m_Talk_FRA = L2_1
