L4_1 = "USER_ADMIN_NULL_NULL"
L3_1.m_CharStrID = L4_1
L4_1 = "하하, 너무 그러지 말게, 부사장."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "はは、あんまりそう責め立てるな、副社長。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Ha ha, don't be so hard on me, Vice President."
L3_1.m_Talk_ENG = L4_1
L4_1 = "哈哈，不要這樣嘛，副總。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ฮ่าฮ่า อย่ารุนแรงกับผมนะรองประธาน"
L3_1.m_Talk_THA = L4_1
L4_1 = "Ha ha, đừng khắt khe với tôi thế, Phó Chủ Tịch."
L3_1.m_Talk_VTN = L4_1
L4_1 = "哈哈，别这样，副总。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Haha. Sei doch nicht so gemein zu mir, Vizepräsidentin."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Ha ha, ne sois pas si dure avec moi, vice-présidente."
L3_1.m_Talk_FRA = L4_1
