L5_1 = "CHARADE2_ACT4_INTERLUDE1@154#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 154
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 5700401
L4_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "USER_ADMIN_NULL_NULL"
L4_1.m_CharStrID = L5_1
L5_1 = "자네도 어느정도 내 사정은 파악하고 있었을 텐데?"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "君もある程度は事情を知っているではないか？"
L4_1.m_Talk_JPN = L5_1
L5_1 = "I'm sure you already knew what kind of situation I was in."
L4_1.m_Talk_ENG = L5_1
L5_1 = "你應該也多少知道我的情況吧？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ผมแน่ใจว่าคุณรู้อยู่แล้วว่าผมอยู่ในสถานการณ์แบบไหน"
L4_1.m_Talk_THA = L5_1
L5_1 = "Tôi chắc rằng cô đã biết tôi đang ở trong tình huống nào."
L4_1.m_Talk_VTN = L5_1
L5_1 = "你应该也了解我的情况不是吗？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Ich bin mir sicher, dass du meine Situation einigermaßen verstanden hast, oder?"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Je suis sûr que tu savais déjà dans quel genre de situation je me trouvais, non ?"
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "CHARADE2_ACT4_INTERLUDE1@155#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 155
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 5700401
