L6_1 = "USER_ADMIN_NULL_NULL"
L5_1.m_CharStrID = L6_1
L6_1 = "그보다 부탁한 조사는 어떻게 되었지?"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "それより、頼んでおいた調査の件はどうだったね？"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Aside from that, how is the investigation that I requested going?"
L5_1.m_Talk_ENG = L6_1
L6_1 = "不過，我拜託你調查的事有結果嗎？"
L5_1.m_Talk_TWN = L6_1
L6_1 = "นอกจากนั้นการสอบสวนที่ผมร้องขอไปเป็นอย่างไรบ้าง?"
L5_1.m_Talk_THA = L6_1
L6_1 = "Ngoài ra, cuộc điều tra mà tôi yêu cầu đang diễn ra thế nào rồi?"
L5_1.m_Talk_VTN = L6_1
L6_1 = "话说，我拜托你调查的怎么样了？"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Wie läuft eigentlich die Untersuchung, mit der ich dich beauftragt hatte?"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Mis à part ça, comment avance l'enquête que je t'ai demandé de mener ?"
L5_1.m_Talk_FRA = L6_1
