L14_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L13_1.m_CharStrID = L14_1
L14_1 = "말씀하신 신비주의 여배우에 대해서는 그다지 유익한 정보는 없군요."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "お話いただいた神秘主義の女優に関してはこれといった情報がありませんでした。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "There was not much useful information about the mysterious actress you mentioned."
L13_1.m_Talk_ENG = L14_1
L14_1 = "你說的那個神秘女演員，沒什麼值得報告的。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ไม่มีข้อมูลที่เป็นประโยชน์มากนักเกี่ยวกับนักแสดงหญิงลึกลับที่คุณพูดถึง"
L13_1.m_Talk_THA = L14_1
L14_1 = "Không có nhiều thông tin hữu ích về nữ diễn viên bí ẩn đó."
L13_1.m_Talk_VTN = L14_1
L14_1 = "对于你说的神秘主义女演员，倒是没什么有价值的情报。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Es gab nicht viele nützliche Informationen über die mysteriöse Schauspielerin, die Sie erwähnt haben."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Je n'ai pas trouvé beaucoup d'informations utiles sur cette mystérieuse actrice que vous avez mentionnée."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "CHARADE2_ACT4_INTERLUDE1@164#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 164
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 5700401
L14_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L14_1.m_CharStrID = L15_1
L15_1 = "아니. 오히려 너무 밝혀진 게 없어서 수상할 정도입니다."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "というより、むしろ情報がなさすぎて怪しいぐらいです。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Essentially, nothing is known about her, which makes it even more suspicious."
L14_1.m_Talk_ENG = L15_1
L15_1 = "不，應該是說乾淨到很可疑。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "โดยพื้นฐานแล้วไม่มีใครรู้เกี่ยวกับเธอซึ่งทำให้น่าสงสัยมากยิ่งขึ้น"
L14_1.m_Talk_THA = L15_1
L15_1 = "Về cơ bản, không có thông tin gì về cô ấy, điều này càng khiến nó đáng nghi hơn."
L14_1.m_Talk_VTN = L15_1
L15_1 = "不，反而是因为没有相关情报，所以才显得很可疑。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Im Wesentlichen ist nichts wirklich über sie bekannt, was sie noch verdächtiger macht."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Pour tout vous dire, on ne sait rien d'elle, ce qui la rend encore plus suspecte."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
