L15_1.m_CutScenID = 5700401
L15_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L15_1.m_CharStrID = L16_1
L16_1 = "매년 영화제를 휩쓸 정도면 파파라치가 붙을 법도 한데, 사생활 쪽에선 빈틈이 없어요."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "毎年映画祭を総なめにしているぐらいですから、パパラッチが追っていてもおかしくないのですが、プライベートは一切漏れていません。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "She must have paparazzi on her tail with all the awards she receives from the film festivals every year, but still nothing is known about her private life."
L15_1.m_Talk_ENG = L16_1
L16_1 = "她每年都從電影節抱回獎項，照理說狗仔應該會盯上她吧？但她的私生活卻從未曝光。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "เธอต้องมีปาปารัสซี่คอยติดตามรางวัลทั้งหมดที่เธอได้รับจากเทศกาลภาพยนตร์ทุกปี แต่ก็ยังไม่มีใครรู้เกี่ยวกับชีวิตส่วนตัวของเธอเลย"
L15_1.m_Talk_THA = L16_1
L16_1 = "Chắc hẳn cô ta đã bị paparazzi theo đuôi với đủ giải thưởng từ các liên hoan phim hàng năm nhưng vẫn chưa có thông tin gì về cuộc sống riêng tư của cô ấy."
L15_1.m_Talk_VTN = L16_1
L16_1 = "她横扫每年的电影节，照理说会被狗仔盯上，但私生活方面却检点得一丝不苟。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Nach all den Auszeichnungen, die sie jedes Jahr auf Filmfestivals erhält, müssten ihr eigentlich stets Paparazzi auf den Fersen sein, aber über ihr Privatleben ist dennoch nichts bekannt."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Elle doit avoir une horde de paparazzis sur le dos avec tous les prix qu'elle reçoit lors des festivals de films chaque année, mais on ne connaît toujours rien sur sa vie privée."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "CHARADE2_ACT4_INTERLUDE1@166#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 166
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 5700401
L16_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L16_1.m_CharStrID = L17_1
L17_1 = "필모그래피도 살펴봤습니다만, 제 취향이 아니라는 것 빼곤 이상한 점은 없었습니다."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "出演作品もざっと見てみましたが、私とは好みが合わないということ以外、おかしな点はありませんでした。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "I even took a look at her filmography. But all I could find out was that her movies were not to my taste."
L16_1.m_Talk_ENG = L17_1
L17_1 = "我還看了她過去拍過的影片，但除了她長得不討我喜歡，其他並沒有可疑之處。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ฉันยังดูผลงานภาพยนตร์ของเธอด้วย แต่สิ่งที่ฉันรู้ก็คือภาพยนตร์ของเธอไม่ถูกใจฉัน"
L16_1.m_Talk_THA = L17_1
L17_1 = "Tôi thậm chí còn xem qua phim của cô ấy. Nhưng tất cả những gì tôi có thể thấy là phim của cô ấy không hợp với sở thích của tôi."
L16_1.m_Talk_VTN = L17_1
L17_1 = "我还看了她的参演目录，除了不是我喜欢的类型这一点外，没有奇怪之处。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Ich habe mir sogar ihre Filmografie angesehen. Aber ich konnte lediglich feststellen, dass ihre Filme nicht meinem Geschmack entsprechen."
L16_1.m_Talk_DEU = L17_1
L17_1 = "J'ai même jeté un œil à sa filmographie. Mais tout ce que j'ai pu découvrir, c'est que ses films n'étaient pas à mon goût."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "CHARADE2_ACT4_INTERLUDE1@167#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 167
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 5700401
L17_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "USER_ADMIN_NULL_NULL"
L17_1.m_CharStrID = L18_1
L18_1 = "뭐, 평단과 대중의 평가가 항상 일치하리라는 법은 없으니까."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "まぁ、評論界と大衆の評価は必ずしも一致するわけではないからな。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Well, there's no law that says the public and critics' opinions should always match."
L17_1.m_Talk_ENG = L18_1
L18_1 = "嗯嗯，評審和大眾的口味向來都是分歧的。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ไม่มีกฎหมายที่ระบุว่าความคิดเห็นของสาธารณชนและนักวิจารณ์ควรตรงกันเสมอไป"
L17_1.m_Talk_THA = L18_1
L18_1 = "Chà, không có luật nào nói rằng ý kiến của công chúng và các nhà phê bình phải luôn khớp với nhau."
L17_1.m_Talk_VTN = L18_1
L18_1 = "好吧，不过评论界和大众的评价向来不可能一致。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Nun, es gibt kein Gesetz, das besagt, dass die Meinungen der Öffentlichkeit und der Kritiker immer übereinstimmen müssen."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Eh bien, il n'y a pas de loi qui dit que les avis du public et des critiques devraient toujours correspondre."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
