L21_1 = "CHARADE2_ACT4_INTERLUDE1@170#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 170
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 5700401
L20_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L20_1.m_CharStrID = L21_1
L21_1 = "그 라이카라는 직원이 말한 우주 탐사 결과에 관해서는 다소 수확이 있었습니다만……."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "そのライカという社員が話していたという宇宙探査の結果については多少の収穫がありましたが……"
L20_1.m_Talk_JPN = L21_1
L21_1 = "I was able to get some information about the space expedition Laika mentioned..."
L20_1.m_Talk_ENG = L21_1
L21_1 = "有關那個叫萊卡的職員說的宇宙探索，是有點收穫……"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ฉันได้ข้อมูลบางอย่างเกี่ยวกับการสำรวจอวกาศที่ไลกากล่าวถึง..."
L20_1.m_Talk_THA = L21_1
L21_1 = "Tôi đã có được một số thông tin về chuyến thám hiểm không gian mà Laika đã đề cập..."
L20_1.m_Talk_VTN = L21_1
L21_1 = "关于那个叫莱卡的职员提到的太空探索结果，倒是有些收获……"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Ich konnte einige Informationen über die von Leica erwähnte Weltraumexpedition in Erfahrung bringen ..."
L20_1.m_Talk_DEU = L21_1
L21_1 = "J'ai pu obtenir des informations sur l'expédition spatiale que Leica a mentionnée..."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "CHARADE2_ACT4_INTERLUDE1@171#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 171
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 5700401
L21_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L21_1.m_CharStrID = L22_1
L22_1 = "탐사대원은 공식적으로는 탐사를 마친 뒤 대기권으로 돌입 중 전원 사망했다고 합니다."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "公式的な発表によると、探査隊員は探査終了後、大気圏に突入する過程で全員死亡したそうです。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "However, the official report states that all expedition members died while returning to the atmosphere."
L21_1.m_Talk_ENG = L22_1
L22_1 = "具探索隊員對外的說法是，在完成探索後進入大氣層時就已經全隊死亡。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "อย่างไรก็ตาม รายงานอย่างเป็นทางการระบุว่าสมาชิก\nคณะสำรวจทั้งหมดเสียชีวิตขณะกลับขึ้นสู่ชั้นบรรยากาศ"
L21_1.m_Talk_THA = L22_1
L22_1 = "Tuy nhiên, báo cáo chính thức cho biết tất cả các thành viên đoàn thám hiểm đã chết khi quay trở lại bầu khí quyển."
L21_1.m_Talk_VTN = L22_1
L22_1 = "官方的说法是，探索队员在完成勘探之后返回至大气层时业已全部身亡。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Der offizielle Bericht besagt jedoch, dass alle Expeditionsmitglieder bei der Rückkehr in die Atmosphäre starben."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Cependant, les rapports officiels indiquent que tous les membres de l'expédition sont morts à leur retour dans l'atmosphère."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "CHARADE2_ACT4_INTERLUDE1@172#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 172
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 5700401
L22_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L22_1.m_CharStrID = L23_1
L23_1 = "관리실패 이후 우주 방면의 감시 자원들은 복구되지 않았으니까요."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "管理失敗以降、宇宙方面の監視資源は復旧されていませんから、詳細は不明です。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Since the space surveillance resources have not been restored after the Administration Failure."
L22_1.m_Talk_ENG = L23_1
L23_1 = "管理失敗以後，宇宙方面的監視資源是無法恢復的。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "เนื่องจากทรัพยากรการเฝ้าระวังอวกาศยังไม่ได้รับการกู้คืนหลังจากความล้มเหลวในการบริหาร"
L22_1.m_Talk_THA = L23_1
L23_1 = "Vì tài nguyên giám sát không gian chưa được khôi phục sau Sai Sót Quản Trị."
L22_1.m_Talk_VTN = L23_1
L23_1 = "鉴于管理失败以后，太空方面的监视资源尚未恢复。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Seit dem Verwaltungsversagen wurden die Überwachungsressourcen im Weltraumbereich nicht wiederhergestellt."
L22_1.m_Talk_DEU = L23_1
L23_1 = "En effet, les ressources de surveillance spatiale n'ont pas été restaurées après la Chute de l'Administration."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "CHARADE2_ACT4_INTERLUDE1@173#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 173
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 5700401
L23_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L23_1.m_CharStrID = L24_1
L24_1 = "대신, 탐사 목표는 달의 뒷면이었다고 하더군요. 양철 깡통이라도 만나러 간 걸까요?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "その代わり、探査目標が月の裏面であったことはわかりました。ブリキ缶にでも会いに行ったのでしょうか？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Instead, I have learned that the objective of the expedition was to find the dark side of the moon. Perhaps they were trying to meet with the junk metal?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "不過，聽說探索的目標是月球的背面，難道是去見鐵罐嗎？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "แต่ฉันได้เรียนรู้ว่าวัตถุประสงค์ของการสำรวจคือการค้นหาด้านมืด\nของดวงจันทร์ บางทีพวกเขากำลังพยายามที่จะพบกับขยะโลหะ?"
L23_1.m_Talk_THA = L24_1
L24_1 = "Thay vào đó, tôi được biết rằng mục tiêu của chuyến thám hiểm là tìm ra phần tối của mặt trăng. Có lẽ họ đang cố gắng gặp mảnh kim loại vụn?"
L23_1.m_Talk_VTN = L24_1
L24_1 = "不过据说，那次探索的目的地在月球的背面。难道是见到那个废铁堆了？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Stattdessen habe ich erfahren, dass das Ziel der Expedition darin bestand, die dunkle Seite des Mondes zu finden. Vielleicht haben sie versucht, sich mit der Blechbüchse zu treffen?"
L23_1.m_Talk_DEU = L24_1
L24_1 = "Par contre, j'ai appris que l'objectif de l'expédition était de trouver la face cachée de la lune. Peut-être essayaient-ils de rencontrer la boîte de conserve en ferraille ?"
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "CHARADE2_ACT4_INTERLUDE1@174#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 174
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 5700401
L24_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "USER_ADMIN_NULL_NULL"
L24_1.m_CharStrID = L25_1
L25_1 = "자네도 여전히 악감정이 남아 있나 보군."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "君もまだ彼女への嫌悪感が残っているようだな。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "I see you are still holding a grudge against her."
L24_1.m_Talk_ENG = L25_1
L25_1 = "看來你對她很有敵意。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ผมเห็นว่าคุณยังคงแค้นเธออยู่"
L24_1.m_Talk_THA = L25_1
L25_1 = "Tôi thấy cô vẫn còn ác cảm với cô ấy."
L24_1.m_Talk_VTN = L25_1
L25_1 = "哈哈，看来你还记恨着她啊。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Du hegst also immer noch einen Groll gegen sie."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Je vois que tu ressens toujours de la rancune à son égard."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "CHARADE2_ACT4_INTERLUDE1@175#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 175
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 5700401
L25_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L25_1.m_CharStrID = L26_1
L26_1 = "침식체 주제에 신 흉내나 냈으니까요."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "侵食体の分際で神のように振舞っていましたから。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Because she is nothing but a C.O. that pretended to be a god."
L25_1.m_Talk_ENG = L26_1
L26_1 = "誰叫她明明是侵蝕體，還敢裝作自己是神。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "เพราะเธอเป็นเพียงผู้บังคับบัญชาที่แสร้งทำเป็นพระเจ้า"
L25_1.m_Talk_THA = L26_1
L26_1 = "Bởi vì cô ấy chẳng là gì ngoài một V.T.A.M giả vờ là một vị thần."
L25_1.m_Talk_VTN = L26_1
L26_1 = "区区侵蚀体，竟敢装作自己是神。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Weil sie nichts anderes als ein C. O. ist, das vorgab, ein Gott zu sein."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Parce qu'elle n'est rien d'autre qu'un O.C. qui prétendait être un dieu."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "CHARADE2_ACT4_INTERLUDE1@176#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 176
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 5700401
L26_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L26_1.m_CharStrID = L27_1
L27_1 = "어쨌거나 그 곳이라면, 현재로선 <color=#ffd34c>세피라</color>에 접촉할 가능성이 가장 높은 지점이겠죠."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "とにかくあそこなら、現時点では最も高確率で<color=#ffd34c>セフィラ</color>に接触できる場所ではありますね。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Anyway, seeing where they were headed, it is somewhere they are most likely to reach <color=#ffd34c>Sephira</color>."
L26_1.m_Talk_ENG = L27_1
L27_1 = "總之如果是那個地方，以現在而言，算是最有可能接觸到<color=#ffd34c>巢穴</color>的地方吧？"
L26_1.m_Talk_TWN = L27_1
L27_1 = "อย่างไรก็ตาม เมื่อเห็นว่าพวกเขากำลังมุ่งหน้าไปทางใด ก็เป็นสถานที่ที่พวกเขามีแนวโน้มที่จะไปถึง <color=#ffd34c>เซฟิร่า</color> มากที่สุด"
L26_1.m_Talk_THA = L27_1
L27_1 = "Dù sao đi nữa, dựa trên hướng họ đang tới, đó là nơi mà họ có nhiều khả năng tiếp cận được <color=#ffd34c>Sephira</color> nhất."
L26_1.m_Talk_VTN = L27_1
L27_1 = "总之如果是那个地方，当前是最有可能接触到<color=#ffd34c>塞菲拉</color>的地点。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Wie auch immer, wenn man sich so anschaut, wohin sie wollten, scheint es irgendwo zu sein, wo sie am wahrscheinlichsten <color=#ffd34c>Sephira</color> erreichen könnten."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Quoi qu'il en soit, l'endroit qu'ils ont atteint est probablement le point le plus proche de <color=#ffd34c>Sephira</color>."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "CHARADE2_ACT4_INTERLUDE1@177#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 177
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 5700401
L27_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L27_1.m_CharStrID = L28_1
L28_1 = "북방합의체가 그것과 접촉해서 뭔가 할 수 있다고는 믿기 어렵습니다만."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "北方合意体がそれと接触したところで何かができるとは思えませんが。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Though it is hard to believe that the Northern Union could do anything if it came into contact with that."
L27_1.m_Talk_ENG = L28_1
L28_1 = "不過我想北方和議會就算和她接觸也無法做什麼吧？"
L27_1.m_Talk_TWN = L28_1
L28_1 = "แม้ว่าจะยากที่จะเชื่อว่าสหภาพฝ่ายเหนือจะทำอะไรก็ได้หากเข้ามาติดต่อกับสิ่งนั้น"
L27_1.m_Talk_THA = L28_1
L28_1 = "Mặc dù thật khó để tin rằng Liên Minh Phía Bắc có thể làm bất cứ điều gì nếu tiếp xúc với điều đó."
L27_1.m_Talk_VTN = L28_1
L28_1 = "虽说很难相信北方联盟和那个接触之后会做出点什么。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Obwohl es schwer zu glauben ist, dass die Nordvereinigung überhaupt etwas damit anfangen könnte, wenn sie damit in Berührung käme."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Bien que j'ai du mal à croire que l'Union du Nord ferait quoi que ce soit si jamais elle entrait en contact avec ça."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "CHARADE2_ACT4_INTERLUDE1@178#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 178
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 5700401
L28_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "USER_ADMIN_NULL_NULL"
L28_1.m_CharStrID = L29_1
L29_1 = "그럴 방법을 찾았다면?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "方法を見つけていたとしたら？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "What if they found a way?"
L28_1.m_Talk_ENG = L29_1
L29_1 = "但如果有找到方法呢？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "เกิดอะไรขึ้นถ้าพวกเขาพบวิธี?"
L28_1.m_Talk_THA = L29_1
L29_1 = "Điều gì sẽ xảy ra nếu họ tìm ra cách?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "但如果找到了方法呢？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Was ist, wenn sie einen Weg gefunden haben?"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Et s'ils avaient trouvé le moyen d'y parvenir ?"
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
