L31_1 = "CHARADE2_ACT4_INTERLUDE1@180#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 180
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 5700401
L30_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "USER_ADMIN_NULL_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "아직은 추측일세. 그렇게 쏘아보지 말게나."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "まだ推測に過ぎないんだ。そんなに睨まないでくれ。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "I am just assuming. Please don't glare at me like that."
L30_1.m_Talk_ENG = L31_1
L31_1 = "這只是推測而已，不要瞪我。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ผมแค่สมมุติ กรุณาอย่ามองผมแบบนั้น"
L30_1.m_Talk_THA = L31_1
L31_1 = "Tôi chỉ giả định thôi. Làm ơn đừng trừng mắt nhìn tôi như thế."
L30_1.m_Talk_VTN = L31_1
L31_1 = "目前只是推测而已，不要那么瞪我。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Es ist nur eine Vermutung. Bitte schau mich nicht so böse an."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Ce n'est qu'une supposition. S'il te plaît, ne me regarde pas comme ça."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
