L35_1 = "CHARADE2_ACT4_INTERLUDE1@184#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 184
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 5700401
L34_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "C"
L35_1 = "m_bCharHologramEffect"
L34_1[L35_1] = true
L35_1 = "출장 나가자마자, 주목을 많이 끌고 계신 것 같더군요."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "出張に出て間もないのに、大変注目を集められているようですね。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "It seems that you have garnered quite a bit of attention as soon as you went on your business trip."
L34_1.m_Talk_ENG = L35_1
L35_1 = "老闆一出差好像就備受矚目呢。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ดูเหมือนว่าคุณจะได้รับความสนใจไม่น้อยทันทีที่คุณเดินทางไปทำธุรกิจ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Có vẻ như ngài đã thu hút được khá nhiều sự chú ý ngay khi đi công tác."
L34_1.m_Talk_VTN = L35_1
L35_1 = "您好像一出差，就备受关注呢。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Es scheint, dass Sie bereits auf Ihrer Geschäftsreise ziemlich viel Aufmerksamkeit auf sich gezogen haben."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Il semble que vous ayez quelque peu attiré l'attention après que vous soyez parti en voyage d'affaires."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "CHARADE2_ACT4_INTERLUDE1@185#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 185
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 5700401
L35_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_Face = "UNIT_PRIDE"
L36_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "C"
L36_1 = "좋은 쪽으로든, 나쁜 쪽으로든 말이죠."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "良くも悪くもです。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Both in good and bad ways, that is."
L35_1.m_Talk_ENG = L36_1
L36_1 = "先不論是好是壞，"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ทั้งในทางดีและไม่ดีนั่นก็คือ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Theo cả ý tốt và xấu."
L35_1.m_Talk_VTN = L36_1
L36_1 = "不管是往好的方面，还是坏的方面。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Sowohl auf gute als auch auf schlechte Weise."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Pour le meilleur comme pour le pire, voyez-vous."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "CHARADE2_ACT4_INTERLUDE1@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 5700401
L36_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "UNIT_IDLE"
L36_1.m_Face = L37_1
L37_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "C"
L37_1 = "모쪼록 조심하시기 바랍니다."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "とにかく、くれぐれもお気を付けください。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Please do be careful."
L36_1.m_Talk_ENG = L37_1
L37_1 = "總之，你小心點吧。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "โปรดระวังด้วย"
L36_1.m_Talk_THA = L37_1
L37_1 = "Xin hãy cẩn thận."
L36_1.m_Talk_VTN = L37_1
L37_1 = "总之，请小心点吧。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Bitte seien Sie vorsichtig."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Je vous prie de faire attention."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 5700401
L37_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L37_1.m_bWaitClick = false
L37_1.m_fWaitTime = 0
L38_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "C_D"
L38_1 = {}
L39_1 = "CHARADE2_ACT4_INTERLUDE1@188#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 188
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 5700401
L38_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "USER_ADMIN_NULL_NULL"
L38_1.m_CharStrID = L39_1
L39_1 = "아, 그리고 한 가지 더. 자네가 조사해줬으면 하는 일이 있네."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "あ、あともう一つ。君に調べてほしいことがある。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Oh, there's one more thing that I want to you take a look at."
L38_1.m_Talk_ENG = L39_1
L39_1 = "那個，還有一件事，我希望你能幫我調查一下。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "อ้อ มีอีกอย่างที่ผมอยากให้คุณลองดู"
L38_1.m_Talk_THA = L39_1
L39_1 = "Ồ, còn một điều nữa tôi muốn cô xem qua."
L38_1.m_Talk_VTN = L39_1
L39_1 = "啊，还有一件事。我希望你能帮我调查一下。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Oh, ich möchte, dass du noch über einen anderen Mitarbeiter Nachforschungen anstellst."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Oh, il y a encore une chose que j'aimerais que tu vérifies."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "CHARADE2_ACT4_INTERLUDE1@189#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 189
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 5700401
L39_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_Face = "UNIT_PRIDE"
L40_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "C"
L40_1 = "여전히 직원 부리는 게 험하시군요."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "相変わらず人使いが荒いですね。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "I see you are still relentless with your employees."
L39_1.m_Talk_ENG = L40_1
L40_1 = "你還是很會使喚員工嘛。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ฉันเห็นว่าคุณยังคงไม่หยุดยั้งกับพนักงานของคุณ"
L39_1.m_Talk_THA = L40_1
L40_1 = "Tôi thấy ngài vẫn tàn nhẫn với nhân viên của mình."
L39_1.m_Talk_VTN = L40_1
L40_1 = "您使唤起员工依旧很不客气啊。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Sie sind, was Ihre Mitarbeiter betrifft, immer noch überaus streng."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Toujours aussi implacable avec vos employés, à ce que je vois."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "CHARADE2_ACT4_INTERLUDE1@190#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 190
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 5700401
L40_1.m_CutScenStrID = "CHARADE2_ACT4_INTERLUDE1"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "UNIT_IDLE"
L40_1.m_Face = L41_1
L41_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "C"
